"python -c \"\nimport json\nwith open('found_line.txt', 'r', encoding='utf-8') as f:\n    line = f.read()\ndata = json.loads(line)\n\n# The content could be in tool_calls -> output or similar\ndef extract_code(obj):\n    if isinstance(obj, str):\n        if 'def compute_human_action_vector' in obj and 'import mujoco' in obj:\n            return obj\n    elif isinstance(obj, dict):\n        for k, v in obj.items():\n            res = extract_code(v)\n            if res: return res\n    elif isinstance(obj, list):\n        for item in obj:\n            res = extract_code(item)\n            if res: return res\n    return None\n\ncode = extract_code(data)\nif code:\n    # If the code was embedded in a diff or view_file output, we need to clean it up\n    # Since it's likely from view_file, we'll strip the line numbers if present\n    import re\n    lines = code.split('\\n')\n    cleaned_lines = []\n    for l in lines:\n        if re.match(r'^\\d+: ', l):\n            cleaned_lines.append(l.split(': ', 1)[1])\n        else:\n            cleaned_lines.append(l)\n    with open('carl_harvest.py', 'w', encoding='utf-8') as f:\n        f.write('\\n'.join(cleaned_lines))\n    print('Recovered successfully.')\nelse:\n    print('Failed to extract code.')\n\""